// Run Once for All Items mode

function normalizeVolumeUnit(unit) {
  const map = {
    'l': 'l', 'liter': 'l', 'liters': 'l', 'litre': 'l', 'litres': 'l',
    'ml': 'ml', 'milliliter': 'ml', 'milliliters': 'ml',
    'm3': 'm3', 'cubic meter': 'm3', 'cubic meters': 'm3', 'cbm': 'm3',
    'cubic foot': 'cubic_foot', 'cubic feet': 'cubic_foot', 'ft3': 'cubic_foot',
    'gallon': 'gallon_us', 'gallons': 'gallon_us', 'gal': 'gallon_us', 'us gallon': 'gallon_us',
    'ig': 'gallon_us', // imperial gallons: no native support, mapped to US gallons as nearest fallback
    'bbl': 'bbl', 'barrel': 'bbl', 'barrels': 'bbl'
  };
  return map[unit.toLowerCase().trim()] || unit.toLowerCase().trim();
}

function normalizeEnergyUnit(unit) {
  const map = {
    'kwh': 'kWh', 'kw h': 'kWh', 'kilowatt hour': 'kWh', 'kilowatt hours': 'kWh',
    'mwh': 'MWh', 'wh': 'Wh', 'gj': 'GJ', 'mj': 'MJ', 'btu': 'Btu'
  };
  return map[unit.toLowerCase().trim()] || unit;
}

const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  let rawOutput = item.json.output;
  let entries = [];

  if (typeof rawOutput === 'string') {
    try {
      const parsed = JSON.parse(rawOutput);
      entries = Array.isArray(parsed) ? parsed : (parsed.entries || []);
    } catch (e) {
      entries = [];
    }
  } else if (rawOutput && Array.isArray(rawOutput.entries)) {
    entries = rawOutput.entries;
  } else if (Array.isArray(rawOutput)) {
    entries = rawOutput;
  }

  let fileName = "unknown";
  try {
    fileName = $('Split Files').itemMatching(i).json.fileName;
  } catch (e) {}

  for (const entry of entries) {
    let activityId = "";
    let parameters = {};

    if (entry.type === "electricity") {
      activityId = "electricity-supply_grid-source_residual_mix";
      parameters = { energy: entry.value, energy_unit: normalizeEnergyUnit(entry.unit) };
    } else if (entry.type === "water") {
      activityId = "water_supply-type_na";
      parameters = { volume: entry.value, volume_unit: normalizeVolumeUnit(entry.unit) };
    } else if (entry.type === "fuel") {
      activityId = "fuel-type_motor_gasoline-fuel_use_na";
      parameters = { volume: entry.value, volume_unit: normalizeVolumeUnit(entry.unit) };
    }

    results.push({
      json: {
        sourceFile: fileName,
        emission_factor: { activity_id: activityId, data_version: "^37" },
        parameters: parameters
      }
    });
  }
}

return results;

// Retrieve the original parsed array from the AI Agent node
// Ensure the node name exactly matches your workflow ('Structured Output Parser' or 'AI Agent')
const aiOutput = $('AI Agent').first().json.output || $('Structured Output Parser').first().json;
const aiEntries = Array.isArray(aiOutput) ? aiOutput : (aiOutput.entries || []);

// Map over the Climatiq API responses
return $input.all().map((item, index) => {
  const apiData = item.json;

  // Match the API response with the corresponding AI entry by index
  const originalAiData = aiEntries[index] || {};

  return {
    json: {
      type: originalAiData.type || "unknown",
      company_name: originalAiData.companey_name || "Unknown",
      consumption_value: apiData.activity_data.activity_value,
      consumption_unit: apiData.activity_data.activity_unit,
      cost_amount: originalAiData.amount || null,
      currency: originalAiData.currency || null,
      total_co2e: parseFloat(apiData.co2e.toFixed(2)), // Rounds to 2 decimal places
      co2e_unit: apiData.co2e_unit,
      emission_region: apiData.emission_factor.region
    }
  };
});
